import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"运算符","description":"","frontmatter":{},"headers":[],"relativePath":"python/basic/beginner/math.md","filePath":"python/basic/beginner/math.md"}`),a={name:`python/basic/beginner/math.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="运算符" tabindex="-1">运算符 <a class="header-anchor" href="#运算符" aria-label="Permalink to “运算符”">​</a></h1><ul><li>运算符用于在程序运行时执行数学或逻辑运算。</li><li>下面示例设置<code>a=10</code> <code>b=20</code></li></ul><h2 id="算术运算符" tabindex="-1">算术运算符 <a class="header-anchor" href="#算术运算符" aria-label="Permalink to “算术运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:center;"><code>+</code></td><td style="text-align:center;">加</td><td style="text-align:center;"><code>a + b</code></td><td style="text-align:center;"><code>10 + 20 = 30</code></td></tr><tr><td style="text-align:center;"><code>-</code></td><td style="text-align:center;">减</td><td style="text-align:center;"><code>a - b</code></td><td style="text-align:center;"><code>10 - 20 = -10</code></td></tr><tr><td style="text-align:center;"><code>*</code></td><td style="text-align:center;">乘</td><td style="text-align:center;"><code>a * b</code></td><td style="text-align:center;"><code>10 * 20 = 200</code></td></tr><tr><td style="text-align:center;"><code>/</code></td><td style="text-align:center;">除</td><td style="text-align:center;"><code>a / b</code></td><td style="text-align:center;"><code>10 / 20 = 0</code></td></tr><tr><td style="text-align:center;"><code>%</code></td><td style="text-align:center;">取余</td><td style="text-align:center;"><code>a % b</code></td><td style="text-align:center;"><code>10 % 20 = 10</code></td></tr><tr><td style="text-align:center;"><code>**</code></td><td style="text-align:center;">幂</td><td style="text-align:center;"><code>a ** b</code></td><td style="text-align:center;"><code>10 ** 2 = 100</code></td></tr><tr><td style="text-align:center;"><code>//</code></td><td style="text-align:center;">除法,向下取整</td><td style="text-align:center;"><code>a // b</code></td><td style="text-align:center;"><code>10 // 3 = 3</code></td></tr></tbody></table><h2 id="关系运算符" tabindex="-1">关系运算符 <a class="header-anchor" href="#关系运算符" aria-label="Permalink to “关系运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:center;"><code>==</code></td><td style="text-align:center;">等于</td><td style="text-align:center;"><code>a == b</code></td><td style="text-align:center;"><code>10 == 20 = false</code></td></tr><tr><td style="text-align:center;"><code>!=</code></td><td style="text-align:center;">不等于</td><td style="text-align:center;"><code>a != b</code></td><td style="text-align:center;"><code>10 != 20 = true</code></td></tr><tr><td style="text-align:center;"><code>&gt;</code></td><td style="text-align:center;">大于</td><td style="text-align:center;"><code>a &gt; b</code></td><td style="text-align:center;"><code>10 &gt; 20 = false</code></td></tr><tr><td style="text-align:center;"><code>&lt;</code></td><td style="text-align:center;">小于</td><td style="text-align:center;"><code>a &lt; b</code></td><td style="text-align:center;"><code>10 &lt; 20 = true</code></td></tr><tr><td style="text-align:center;"><code>&gt;=</code></td><td style="text-align:center;">大于等于</td><td style="text-align:center;"><code>a &gt;= b</code></td><td style="text-align:center;"><code>10 &gt;= 20 = false</code></td></tr><tr><td style="text-align:center;"><code>&lt;=</code></td><td style="text-align:center;">小于等于</td><td style="text-align:center;"><code>a &lt;= b</code></td><td style="text-align:center;"><code>10 &lt;= 20 = true</code></td></tr></tbody></table><h2 id="逻辑运算符" tabindex="-1">逻辑运算符 <a class="header-anchor" href="#逻辑运算符" aria-label="Permalink to “逻辑运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:center;"><code>and</code></td><td style="text-align:center;">布尔&quot;与&quot;</td><td style="text-align:center;"><code>a and b</code></td><td style="text-align:center;"><code>true</code></td></tr><tr><td style="text-align:center;"><code>or</code></td><td style="text-align:center;">布尔&quot;或&quot;</td><td style="text-align:center;"><code>a or b</code></td><td style="text-align:center;"><code>true</code></td></tr><tr><td style="text-align:center;"><code>not</code></td><td style="text-align:center;">布尔&quot;非&quot;</td><td style="text-align:center;"><code>not (a and b)</code></td><td style="text-align:center;"><code>false</code></td></tr></tbody></table><h2 id="位运算符" tabindex="-1">位运算符 <a class="header-anchor" href="#位运算符" aria-label="Permalink to “位运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&amp;</code></td><td style="text-align:center;">按位与</td><td style="text-align:center;"><code>a &amp; b</code></td><td style="text-align:center;"><code>10 &amp; 20 = 0</code></td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:center;">按位或</td><td style="text-align:center;"><code>a | b</code></td><td style="text-align:center;"><code>10 | 20 = 30</code></td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:center;">按位异或</td><td style="text-align:center;"><code>a ^ b</code></td><td style="text-align:center;"><code>10 ^ 20 = 30</code></td></tr><tr><td style="text-align:left;"><code>&lt;&lt;</code></td><td style="text-align:center;">左移</td><td style="text-align:center;"><code>a &lt;&lt; b</code></td><td style="text-align:center;"><code>10 &lt;&lt; 20 = 1000000</code></td></tr><tr><td style="text-align:left;"><code>&gt;&gt;</code></td><td style="text-align:center;">右移</td><td style="text-align:center;"><code>a &gt;&gt; b</code></td><td style="text-align:center;"><code>10 &gt;&gt; 20 = 0</code></td></tr></tbody></table><h2 id="赋值运算符" tabindex="-1">赋值运算符 <a class="header-anchor" href="#赋值运算符" aria-label="Permalink to “赋值运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:center;"><code>=</code></td><td style="text-align:center;">赋值</td><td style="text-align:center;"><code>a = b</code></td><td style="text-align:center;"><code>10 = 20</code></td></tr><tr><td style="text-align:center;"><code>+=</code></td><td style="text-align:center;">加后赋值</td><td style="text-align:center;"><code>a += b</code></td><td style="text-align:center;"><code>10 += 20 = 30</code></td></tr><tr><td style="text-align:center;"><code>-=</code></td><td style="text-align:center;">减后赋值</td><td style="text-align:center;"><code>a -= b</code></td><td style="text-align:center;"><code>10 -= 20 = -10</code></td></tr><tr><td style="text-align:center;"><code>*=</code></td><td style="text-align:center;">乘后赋值</td><td style="text-align:center;"><code>a *= b</code></td><td style="text-align:center;"><code>10 *= 20 = 200</code></td></tr><tr><td style="text-align:center;"><code>/=</code></td><td style="text-align:center;">除后赋值</td><td style="text-align:center;"><code>a /= b</code></td><td style="text-align:center;"><code>10 /= 20 = 0</code></td></tr><tr><td style="text-align:center;"><code>%=</code></td><td style="text-align:center;">取余后赋值</td><td style="text-align:center;"><code>a %= b</code></td><td style="text-align:center;"><code>10 %= 20 = 10</code></td></tr></tbody></table><h2 id="成员运算符" tabindex="-1">成员运算符 <a class="header-anchor" href="#成员运算符" aria-label="Permalink to “成员运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:center;"><code>in</code></td><td style="text-align:center;">在指定的序列中找到值返回 True，否则返回 False。</td><td style="text-align:center;"><code>x=1</code> <code>y=[1,2]</code> <code>x in y</code></td><td style="text-align:center;"><code>true</code></td></tr><tr><td style="text-align:center;"><code>not in</code></td><td style="text-align:center;">在指定的序列中没有找到值返回 True，否则返回 False。</td><td style="text-align:center;"><code>x=5</code> <code>y=[1,2]</code> <code>x not in y</code></td><td style="text-align:center;"><code>true</code></td></tr></tbody></table><h2 id="身份运算符" tabindex="-1">身份运算符 <a class="header-anchor" href="#身份运算符" aria-label="Permalink to “身份运算符”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">运算符</th><th style="text-align:center;">描述</th><th style="text-align:center;">表达式</th><th style="text-align:center;">结果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>is</code></td><td style="text-align:center;">is 是判断两个标识符是不是引用自一个对象</td><td style="text-align:center;"><code>x=20</code> <code>y=20</code> <code>x is y</code></td><td style="text-align:center;"><code>true</code></td></tr><tr><td style="text-align:left;"><code>is not</code></td><td style="text-align:center;">is not 是判断两个标识符是不是引用自不同对象</td><td style="text-align:center;"><code>x=20</code> <code>y=20</code> <code>x is not y</code></td><td style="text-align:center;"><code>false</code></td></tr></tbody></table>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};